using System;
using Framework.Grid;
using Framework.AI.Perception;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// グリッド聴覚センサーの動作を検証する。
    /// </summary>
    public sealed class GridHearingSensorTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [Tooltip("開始時にテストを実行する。")]
        [SerializeField]
        private bool runTestsOnStart = true;

        /// <summary>
        /// 成功したテスト数。
        /// </summary>
        private int passedCount;

        /// <summary>
        /// 失敗したテスト数。
        /// </summary>
        private int failedCount;

        /// <summary>
        /// 開始時のテスト実行。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunTests();
            }
        }

        /// <summary>
        /// 全テストを実行する。
        /// </summary>
        [ContextMenu("Run Tests")]
        public void RunTests()
        {
            passedCount = 0;
            failedCount = 0;

            Debug.Log(
                "===== GridHearingSensor テスト開始 =====",
                this);

            TestConfiguration();
            TestDistance();
            TestHearing();
            TestConfidence();
            TestObservation();
            TestLifecycle();

            Debug.Log(
                $"===== テスト終了：成功 {passedCount}件 / " +
                $"失敗 {failedCount}件 =====",
                this);
        }

        /// <summary>
        /// テスト用の聴覚センサーを生成する。
        /// </summary>
        /// <param name="map">テスト用マップ</param>
        /// <returns>聴覚センサー</returns>
        private GridHearingSensor<bool> CreateSensor(
            out GridMap<bool> map)
        {
            // trueを通路、falseを壁として扱う。
            var newMap = new GridMap<bool>(
                7,
                7,
                position => true);

            map = newMap;

            return new GridHearingSensor<bool>(
                newMap,
                position => newMap.GetCell(position),
                8f,
                0.5f);
        }

        /// <summary>
        /// 初期設定と聴覚範囲を検証する。
        /// </summary>
        private void TestConfiguration()
        {
            using (var sensor = CreateSensor(out _))
            {
                Debug.Assert(
                    sensor.Range == 8f,
                    "初期聴覚範囲", this);
                Check(sensor.Range == 8f,
                    "初期聴覚範囲");

                Debug.Assert(
                    sensor.Sensitivity == 0.5f,
                    "初期聴覚感度", this);
                Check(sensor.Sensitivity == 0.5f,
                    "初期聴覚感度");

                Debug.Assert(
                    sensor.IsEnabled,
                    "初期有効状態", this);
                Check(sensor.IsEnabled,
                    "初期有効状態");

                bool correctRange = Mathf.Approximately(
                    sensor.GetEffectiveRange(0.5f), 4f);

                Debug.Assert(
                    correctRange,
                    "通常音量の実効範囲", this);
                Check(correctRange,
                    "通常音量の実効範囲");

                sensor.Configure(8f, 1f);

                bool highSensitivity = Mathf.Approximately(
                    sensor.GetEffectiveRange(0.5f), 6f);

                Debug.Assert(
                    highSensitivity,
                    "高感度時の実効範囲", this);
                Check(highSensitivity,
                    "高感度時の実効範囲");
            }
        }

        /// <summary>
        /// 通路距離とキャッシュを検証する。
        /// </summary>
        private void TestDistance()
        {
            using (var sensor = CreateSensor(out var map))
            {
                Vector2Int origin = new Vector2Int(1, 1);
                Vector2Int source = new Vector2Int(3, 1);

                int distance = sensor.GetDistance(
                    origin, source);

                Debug.Assert(
                    distance == 2,
                    "直線通路距離", this);
                Check(distance == 2,
                    "直線通路距離");

                long count = sensor.RecalculationCount;

                sensor.GetDistance(origin, source);

                bool cacheUsed =
                    sensor.RecalculationCount == count;

                Debug.Assert(
                    cacheUsed,
                    "距離キャッシュ再利用", this);
                Check(cacheUsed,
                    "距離キャッシュ再利用");

                // 直線経路を壁で遮断する。
                map.SetCell(new Vector2Int(2, 1), false);

                distance = sensor.GetDistance(
                    origin, source);

                Debug.Assert(
                    distance == 4,
                    "壁を迂回する通路距離", this);
                Check(distance == 4,
                    "壁を迂回する通路距離");

                bool recalculated =
                    sensor.RecalculationCount == count + 1;

                Debug.Assert(
                    recalculated,
                    "地形変更後の再計算", this);
                Check(recalculated,
                    "地形変更後の再計算");

                distance = sensor.GetDistance(
                    origin,
                    new Vector2Int(-1, 0));

                Debug.Assert(
                    distance == -1,
                    "範囲外の音源", this);
                Check(distance == -1,
                    "範囲外の音源");
            }
        }

        /// <summary>
        /// 聴覚認識の可否を検証する。
        /// </summary>
        private void TestHearing()
        {
            using (var sensor = CreateSensor(out var map))
            {
                Vector2Int origin = new Vector2Int(1, 1);
                Vector2Int source = new Vector2Int(3, 1);

                bool heard = sensor.CanHear(
                    origin, source, 0.5f);

                Debug.Assert(
                    heard,
                    "通常足音の認識", this);
                Check(heard,
                    "通常足音の認識");

                heard = sensor.CanHear(
                    origin, source, 0f);

                Debug.Assert(
                    !heard,
                    "無音時は認識しない", this);
                Check(!heard,
                    "無音時は認識しない");

                heard = sensor.CanHear(
                    origin,
                    new Vector2Int(5, 1),
                    0.5f);

                Debug.Assert(
                    heard,
                    "聴覚範囲の境界", this);
                Check(heard,
                    "聴覚範囲の境界");

                heard = sensor.CanHear(
                    origin,
                    new Vector2Int(6, 1),
                    0.5f);

                Debug.Assert(
                    !heard,
                    "聴覚範囲外", this);
                Check(!heard,
                    "聴覚範囲外");

                // 音源への通路を完全に遮断する。
                map.SetCell(new Vector2Int(2, 1), false);
                map.SetCell(new Vector2Int(4, 1), false);
                map.SetCell(new Vector2Int(3, 0), false);
                map.SetCell(new Vector2Int(3, 2), false);

                heard = sensor.CanHear(
                    origin, source, 1f);

                Debug.Assert(
                    !heard,
                    "隔離された音源", this);
                Check(!heard,
                    "隔離された音源");
            }
        }

        /// <summary>
        /// 音の認識信頼度を検証する。
        /// </summary>
        private void TestConfidence()
        {
            using (var sensor = CreateSensor(out _))
            {
                Vector2Int origin = new Vector2Int(1, 1);

                float near = sensor.GetConfidence(
                    origin,
                    new Vector2Int(2, 1),
                    0.5f);

                float far = sensor.GetConfidence(
                    origin,
                    new Vector2Int(4, 1),
                    0.5f);

                Debug.Assert(
                    near > far,
                    "距離による信頼度減衰", this);
                Check(near > far,
                    "距離による信頼度減衰");

                bool validRange =
                    near > 0f && near <= 1f;

                Debug.Assert(
                    validRange,
                    "信頼度の有効範囲", this);
                Check(validRange,
                    "信頼度の有効範囲");

                float confidence = sensor.GetConfidence(
                    origin, origin, 0.5f);

                Debug.Assert(
                    confidence == 1f,
                    "同一セルの信頼度", this);
                Check(confidence == 1f,
                    "同一セルの信頼度");

                confidence = sensor.GetConfidence(
                    origin,
                    new Vector2Int(6, 1),
                    0.5f);

                Debug.Assert(
                    confidence == 0f,
                    "範囲外の信頼度", this);
                Check(confidence == 0f,
                    "範囲外の信頼度");

                confidence = sensor.GetConfidence(
                    origin, origin, float.NaN);

                Debug.Assert(
                    confidence == 0f,
                    "無効な音量の拒否", this);
                Check(confidence == 0f,
                    "無効な音量の拒否");
            }
        }

        /// <summary>
        /// 聴覚刺激の生成を検証する。
        /// </summary>
        private void TestObservation()
        {
            using (var sensor = CreateSensor(out _))
            {
                Guid id = Guid.NewGuid();

                Vector2Int origin = new Vector2Int(1, 1);
                Vector2Int source = new Vector2Int(3, 1);

                bool result = sensor.TryObserve(
                    id,
                    origin,
                    source,
                    0.5f,
                    10d,
                    out var stimulus);

                Debug.Assert(
                    result,
                    "聴覚刺激の生成", this);
                Check(result,
                    "聴覚刺激の生成");

                bool correctType =
                    stimulus.Type == PerceptionType.Hearing;

                Debug.Assert(
                    correctType,
                    "聴覚刺激の種類", this);
                Check(correctType,
                    "聴覚刺激の種類");

                bool correctPosition =
                    stimulus.Position == source;

                Debug.Assert(
                    correctPosition,
                    "聴覚刺激の位置", this);
                Check(correctPosition,
                    "聴覚刺激の位置");

                bool correctData =
                    stimulus.SourceId == id &&
                    stimulus.Timestamp == 10d &&
                    stimulus.IsValid;

                Debug.Assert(
                    correctData,
                    "聴覚刺激の基本情報", this);
                Check(correctData,
                    "聴覚刺激の基本情報");

                result = sensor.TryObserve(
                    Guid.Empty,
                    origin,
                    source,
                    0.5f,
                    10d,
                    out stimulus);

                Debug.Assert(
                    !result && !stimulus.IsValid,
                    "無効な音源識別子", this);
                Check(!result && !stimulus.IsValid,
                    "無効な音源識別子");
            }
        }

        /// <summary>
        /// 無効化と解放処理を検証する。
        /// </summary>
        private void TestLifecycle()
        {
            using (var sensor = CreateSensor(out var map))
            {
                Vector2Int origin = new Vector2Int(1, 1);
                Vector2Int source = new Vector2Int(2, 1);

                sensor.Configure(0f, 0.5f);

                Debug.Assert(
                    !sensor.IsEnabled,
                    "聴覚の無効化", this);
                Check(!sensor.IsEnabled,
                    "聴覚の無効化");

                bool heard = sensor.CanHear(
                    origin, source, 1f);

                Debug.Assert(
                    !heard,
                    "無効化中の認識拒否", this);
                Check(!heard,
                    "無効化中の認識拒否");

                sensor.Configure(8f, 0.5f);

                heard = sensor.CanHear(
                    origin, source, 0.5f);

                Debug.Assert(
                    heard,
                    "聴覚の再有効化", this);
                Check(heard,
                    "聴覚の再有効化");

                sensor.Dispose();
                sensor.Dispose();

                Debug.Assert(
                    sensor.IsDisposed,
                    "複数回の解放", this);
                Check(sensor.IsDisposed,
                    "複数回の解放");

                map.SetCell(source, false);

                bool safe =
                    !sensor.CanHear(origin, source, 1f) &&
                    sensor.GetDistance(origin, source) == -1;

                Debug.Assert(
                    safe,
                    "解放後の安全性", this);
                Check(safe,
                    "解放後の安全性");
            }
        }

        /// <summary>
        /// テスト結果を集計して出力する。
        /// </summary>
        /// <param name="condition">検証結果</param>
        /// <param name="testName">テスト名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】 {testName}",
                    this);
            }
        }
    }
}
